// TH15 v1.00b Stage 1 mid-stage wave 2.
// Source st01.ecl.txt:932-950 (MainSub00 entry), deps 98-113 / 115-164 / 387-394 / 760-777.
// Seven alternating trios; every trio is Blue/Red(e)/Blue but only the centre girl fires.

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

// TH15 type 4 -> existing modern catalog slot; source colour 6.
const TH15_BALL: int = 416;
const BALL_COLOR: int = 6;

// GirlA02_at: VELTIME 0x200000, 60 frames from speed 3.0 to 7.0, keep angle (Lunatic only).
xformdef SPEED_RAMP_7(unused: int) {
    set_accel(0.066666fx);
    wait(60);
    set_accel(0fx);
}

// GirlA02_at 115-164. Firing is the async half of GirlRedA02e (774).
async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    var delay: int = 90;
    var speed: fx = 1.5fx;
    var bursts: int = 1;
    var gap: int = 30;
    if rank == RANK_HARD {
        delay = 30;
        speed = 2fx;
        bursts = 4;
        gap = 20;
    }
    if rank == RANK_LUNATIC {
        delay = 30;
        speed = 3fx;
        bursts = 20;
        gap = 5;
    }
    wait(delay);
    for i in 0..bursts {
        // etAim(0,0), etCount(0,1,1): one aimed shot per etOn.
        if rank == RANK_LUNATIC {
            _ = fire(TH15_BALL, BALL_COLOR, $self_x, $self_y, speed, aim_player(), SPEED_RAMP_7(0), none);
        } else {
            _ = fire(TH15_BALL, BALL_COLOR, $self_x, $self_y, speed, aim_player(), none, none);
        }
        wait(gap);
    }
}

// GirlA02 98-113 plus the two wrapper bodies (387-394, 760-777).
// dir/down are already mirror-resolved: enmCreateM girls fly 180-angle, x velocity negated.
async sub girl(dir: angle, down: angle, firing: int) {
    set_hurtbox(12fx); // source setHurtbox 24.0f -> radius 12
    set_hitbox(8fx);   // source setHitbox 16.0f -> radius 8
    set_invuln(65535);
    if firing != 0 { spawn girl_fire(); }
    move_vel(0, dir, 3fx, EASE_LINEAR);      // moveVel(1.1780972f, 3.0f)
    wait(30);
    move_vel(60, down, 2fx, EASE_LINEAR);    // moveVelTime(60,0,0.0f,2.0f)
    wait(60);
    move_speed(60, 3fx, EASE_LINEAR);        // moveVelTime(60,0,-999999.0f,3.0f): angle kept
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    for round in 0..7 {
        // enmCreate x3 at %A=-192 (-32 / 0 / +32, y -16 / -28 / -40), no mirror.
        _ = spawn_enemy(-224fx, -16fx, 100, 0, 1000, 0, girl(67.5deg, 0deg, 0));
        _ = spawn_enemy(-192fx, -28fx, 100, 0, 1000, 0, girl(67.5deg, 0deg, 1));
        _ = spawn_enemy(-160fx, -40fx, 100, 0, 1000, 0, girl(67.5deg, 0deg, 0));
        wait(30);
        // enmCreateM x3 at %A=+192 (y -40 / -28 / -16), mirror bit set.
        _ = spawn_enemy(160fx, -40fx, 100, 0, 1000, 0, girl(112.5deg, 180deg, 0));
        if global(GVAR_RANK) == RANK_EASY {
            // !E branch: GirlRedA02 (761) does not fire.
            _ = spawn_enemy(192fx, -28fx, 100, 0, 1000, 0, girl(112.5deg, 180deg, 0));
        } else {
            _ = spawn_enemy(192fx, -28fx, 100, 0, 1000, 0, girl(112.5deg, 180deg, 1));
        }
        _ = spawn_enemy(224fx, -16fx, 100, 0, 1000, 0, girl(112.5deg, 180deg, 0));
        wait(30);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
